// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public { c = new SimpleWallet(); rec = new Recorder(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.deal(address(c), type(uint128).max);
        vm.prank(c.owner());
        c.sendMoney(address(rec), amount);
        assertTrue(rec.received() == amount);
    }
}

contract Recorder {
    uint256 public received;
    fallback() external payable { received += msg.value; }
}
